# AI generated from scripts.md; do not edit by hand.
import sys as _sys
if _sys.version_info < (3, 14):
    _sys.exit("this needs Python 3.14+ (argparse color=False); found " + ".".join(map(str, _sys.version_info[:3])))
import argparse, difflib, hashlib, json, os, re, subprocess, sys, threading, time, uuid, webbrowser
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import parse_qs, urlparse

ROOT = Path(__file__).resolve().parent.parent
GRADES, RESULTS, DATA, QUEUE = (ROOT / d for d in ("grades", "results", "data", "webui-review-queue"))
LEARN = ROOT / "learning" / "interactive-feedback"
AI_BEGIN, AI_END = "<!-- AI BEGIN -->", "<!-- AI END -->"
MAX_DIFF = 150_000
NAME = r"[\w.-]+"
DISK = re.compile(r"^[A-Za-z0-9-]+_[\w.-]+$")
RUN = re.compile(r"^[\w][\w.-]*$")


class Err(Exception):
    def __init__(self, msg, code=400):
        super().__init__(msg)
        self.code = code


# ---------------------------------------------------------------- configs

def parse_cfg(path):
    kv = {}
    for line in path.read_text().splitlines():
        line = line.strip()
        if line and not line.startswith("#") and "=" in line:
            k, v = line.split("=", 1)
            kv[k.strip()] = v.strip()
    return kv


def canonical(repo_file):
    m = re.search(rf"github\.com/({NAME})/({NAME})", repo_file.read_text())
    return f"{m[1]}/{m[2]}" if m else None


def find_config(disk):
    """(cfg path, repo file path) of the config whose repo file names this repo."""
    for cfg in sorted(ROOT.glob("*.cfg")):
        if cfg.is_symlink() or cfg.name == "active-config.cfg":
            continue
        rel = parse_cfg(cfg).get("repo")
        rf = ROOT / rel if rel else None
        if rf and rf.is_file() and (canonical(rf) or "").replace("/", "_", 1) == disk:
            return cfg, rf
    return None


def ensure_config(owner, name):
    """Find or create the config for a repo; returns (cfg, repo file, created files)."""
    disk = f"{owner}_{name}"
    found = find_config(disk)
    if found:
        return (*found, [])
    base = name
    if (ROOT / f"{base}.cfg").exists() or (ROOT / "repos" / f"{base}.md").exists():
        base = f"{owner}-{name}"
    text = (ROOT / "repos" / "example.md").read_text()
    text = text.replace("github.com/<owner>/<name>", f"github.com/{owner}/{name}", 1)
    text = re.sub(r"github\.com/<mirror-owner>/<name>.*?\n\n", "", text, flags=re.S)
    text = re.sub(r"The mirror line is optional\..*?\n\n", "", text, flags=re.S)
    text = re.sub(r"^- <(login|substring)>\n", "", text, flags=re.M)
    rf, cfg = ROOT / "repos" / f"{base}.md", ROOT / f"{base}.cfg"
    rf.write_text(f"{AI_BEGIN}\n{text.rstrip()}\n{AI_END}\n")
    cfg.write_text(f"# AI generated by webui.py\nrepo=repos/{base}.md\n")
    return cfg, rf, [cfg.name, f"repos/{base}.md"]


def current_run(rf):
    h = hashlib.md5()
    files = [ROOT / "prompt.md", ROOT / "rubric.md", ROOT / "guidelines.md",
             *sorted((ROOT / "learning").glob("*.md")), rf]
    for f in files:
        h.update(f.read_bytes())
    return "web-" + h.hexdigest()[:8]


def check_repo(disk):
    if not isinstance(disk, str) or not DISK.match(disk):
        raise Err("bad repo")
    found = find_config(disk)
    if not found:
        raise Err(f"no config for {disk}")
    return found


def check_run(run):
    if not isinstance(run, str) or not RUN.match(run):
        raise Err("bad run id")
    return run


def check_pr(n):
    try:
        return int(n)
    except (TypeError, ValueError):
        raise Err("bad PR number")


# ------------------------------------------------------------------- jobs

JOBS = {}


class Job:
    def __init__(self):
        self.id = uuid.uuid4().hex[:12]
        self.status, self.log, self.result, self.error = "running", [], None, None
        JOBS[self.id] = self

    def view(self):
        return {"id": self.id, "status": self.status, "log": self.log[-200:],
                "result": self.result, "error": self.error}


def start_job(fn):
    job = Job()

    def run():
        try:
            fn(job)
            job.status = "done"
        except Err as e:
            job.status, job.error = "error", str(e)
        except Exception as e:
            job.status, job.error = "error", f"{type(e).__name__}: {e}"

    threading.Thread(target=run, daemon=True).start()
    return job


def run_script(job, cfg, script, *args):
    job.log.append("$ " + " ".join([script, *args]))
    p = subprocess.Popen([sys.executable, "-I", str(ROOT / "scripts" / f"{script}.py"),
                          "--config", str(cfg), *args],
                         stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, cwd=ROOT)
    out = []
    for line in p.stdout:
        line = line.rstrip("\n")
        out.append(line)
        job.log.append(line)
    return p.wait(), "\n".join(out)


def ask_model(prompt, cfg):
    """One model call through scripts/agent.py (claude, codex or a command; see its --agent)."""
    r = subprocess.run([sys.executable, "-I", str(ROOT / "scripts" / "agent.py"), "--config", str(cfg)],
                       input=prompt, capture_output=True, text=True)
    if r.returncode:
        raise Err("the agent failed: " + r.stderr.strip()[-300:])
    txt = r.stdout.strip()
    try:
        return json.loads(txt[txt.index("{"):txt.rindex("}") + 1])
    except ValueError:
        raise Err(f"bad model output: {txt[:200]} {r.stderr[:200]}")


# ---------------------------------------------------------------- start

def api_start(b, role):
    mode, url = b.get("mode"), (b.get("url") or "").strip()
    if mode == "single":
        m = re.match(rf"^(?:https?://)?github\.com/({NAME})/({NAME})/pull/(\d+)", url)
        if not m:
            raise Err("expected a pull request link: https://github.com/<owner>/<name>/pull/<n>")
        owner, name, n = m[1], m[2], int(m[3])
    elif mode == "iterative":
        m = re.match(rf"^(?:(?:https?://)?github\.com/)?({NAME})/({NAME}?)(?:\.git)?(?:/.*)?$", url)
        if not m:
            raise Err("expected a repository link: https://github.com/<owner>/<name>")
        owner, name, n = m[1], m[2], None
    else:
        raise Err("bad mode")
    cfg, rf, created = ensure_config(owner, name)
    disk, run = f"{owner}_{name}", current_run(rf)
    repo = f"{owner}/{name}"

    def work(job):
        for c in created:
            job.log.append(f"created {c} (check Size classification in the repo file)")
        out = RESULTS / disk / run
        if n is not None:
            code, text = run_script(job, cfg, "fetch_prs", "--repo", repo, "--pr", str(n))
            if re.search(rf"^ignored {n}$", text, re.M):
                raise Err(f"PR {n} is ignored by the repo file (author or title); not graded")
            if code:
                raise Err("fetch failed")
            code, _ = run_script(job, cfg, "grade", "--repo", disk, "--run-id", run,
                                 "--pr", str(n), "-j", "1")
            if not (out / f"{n}.json").exists():
                raise Err("grading failed")
            job.result = {"repo": disk, "run": run, "prs": [n]}
        else:
            code, _ = run_script(job, cfg, "fetch_prs", "--repo", repo)
            if code:
                raise Err("fetch failed")
            job.result = {"repo": disk, "run": run}
            run_script(job, cfg, "grade", "--repo", disk, "--run-id", run, "-j", "4")

    return {"job": start_job(work).id, "repo": disk, "run": run, "created": created}


# ----------------------------------------------------------------- data

def meta_of(disk, n):
    f = DATA / disk / "prs" / str(n) / "meta.json"
    return json.loads(f.read_text()) if f.exists() else {}


def read_grade(disk, n):
    f = GRADES / disk / f"{n}.txt"
    if not f.exists():
        return {"mine": "", "notes": ""}
    head, _, notes = f.read_text().partition("notes:")
    return {"mine": head.partition(":")[2].strip(), "notes": notes.strip()}


RESPONSE = re.compile(r"^c(\d+):\s*(.*)$")


def split_notes(notes, count):
    """Split the notes into general text and the `c<i>: ...` response to each comment."""
    general, responses = [], [""] * count
    for line in notes.splitlines():
        m = RESPONSE.match(line)
        if m and 1 <= int(m[1]) <= count:
            responses[int(m[1]) - 1] = m[2].strip()
        else:
            general.append(line)
    return "\n".join(general).strip(), responses


def api_list(q):
    disk, run = q["repo"], check_run(q["run"])
    check_repo(disk)
    base = DATA / disk
    sel = base / "selected.json"
    info = json.loads(sel.read_text()) if sel.exists() else {}
    nums = sorted(map(int, info), reverse=True) if info else sorted(
        (int(d.name) for d in (base / "prs").glob("*") if d.name.isdigit()), reverse=True)
    out = []
    for n in nums:
        m = meta_of(disk, n)
        rf_ = RESULTS / disk / run / f"{n}.json"
        out.append({"pr": n, "title": m.get("title", ""), "author": m.get("author", ""),
                    "bucket": info.get(str(n), {}).get("bucket"), "size": info.get(str(n), {}).get("size"),
                    "graded": rf_.exists(), "model": json.loads(rf_.read_text()).get("overall") if rf_.exists() else None,
                    "reviewed": (GRADES / disk / f"{n}.txt").exists(), "mine": read_grade(disk, n)["mine"]})
    return out


def api_recent():
    """The 20 PRs with saved feedback that were touched last, newest first, across repos."""
    out, known = [], {}
    for f in sorted(GRADES.glob("*/*.txt"), key=lambda f: f.stat().st_mtime, reverse=True):
        disk = f.parent.name
        if not DISK.match(disk) or not f.stem.isdigit():
            continue
        if disk not in known:
            known[disk] = find_config(disk) is not None
        if not known[disk]:
            continue
        name = disk.replace("_", "/", 1)
        out.append({"repo": name, "pr": int(f.stem), "title": meta_of(disk, f.stem).get("title", ""),
                    "mine": read_grade(disk, f.stem)["mine"],
                    "url": f"https://github.com/{name}/pull/{f.stem}"})
        if len(out) == 20:
            break
    return out


def api_pr(q):
    disk, run, n = q["repo"], check_run(q["run"]), check_pr(q["pr"])
    _, rf = check_repo(disk)
    f = RESULTS / disk / run / f"{n}.json"
    if not f.exists():
        raise Err("not graded yet")
    res = json.loads(f.read_text())
    comments = [c if isinstance(c, dict) else {"sentiment": None, "text": c}
                for c in res.get("comments", [])]
    m, g = meta_of(disk, n), read_grade(disk, n)
    notes, responses = split_notes(g["notes"], len(comments))
    d = DATA / disk / "prs" / str(n) / "diff.patch"
    return {"pr": n, "title": m.get("title", ""), "author": m.get("author", ""),
            "url": f"https://github.com/{disk.replace('_', '/', 1)}/pull/{n}",
            "state": m.get("state", ""), "body": m.get("body", ""), "model": res.get("overall"),
            "scores": res.get("scores"), "with_tests": res.get("overall_with_tests"),
            "files": res.get("files"), "dirs": res.get("dirs"),
            "comments": comments, "effort": res.get("effort"), "mine": g["mine"], "notes": notes,
            "responses": responses, "refs": refs_of(disk, run, n), "diff": d.read_text() if d.exists() else "",
            "run_stale": run != current_run(rf)}


def annotations_file(disk, run, n):
    return RESULTS / disk / run / "annotations" / f"{n}.json"


def api_annotate(b, role):
    disk, run, n = b["repo"], check_run(b["run"]), check_pr(b["pr"])
    cfg, _ = check_repo(disk)

    def work(job):
        f = annotations_file(disk, run, n)
        if not f.exists():
            code, text = run_script(job, cfg, "explain", "--repo", disk, "--annotate-source", run, str(n))
            if code:
                raise Err("annotation failed")
            try:
                data = json.loads(text[text.index("{"):text.rindex("}") + 1])
            except ValueError:
                raise Err("annotation failed: bad output")
            f.parent.mkdir(parents=True, exist_ok=True)
            f.write_text(json.dumps(data, indent=2))
        job.result = {"refs": refs_of(disk, run, n)}

    return {"job": start_job(work).id}


def refs_of(disk, run, n):
    """Per comment (parallel to the comments) the diff locations it is about; None if not annotated yet."""
    f = annotations_file(disk, run, n)
    if not f.exists():
        return None
    count = len(json.loads((RESULTS / disk / run / f"{n}.json").read_text()).get("comments", []))
    refs = [[] for _ in range(count)]
    for item in json.loads(f.read_text()).get("annotations", []):
        if 1 <= item["comment"] <= count:
            refs[item["comment"] - 1] = item["refs"]
    return refs


def api_feedback(b, role):
    disk, n = b["repo"], check_pr(b["pr"])
    check_repo(disk)
    mine = str(b.get("mine") or "")
    if mine not in ("", "1", "2", "3", "4", "5"):
        raise Err("bad grade")
    lines = [(b.get("notes") or "").strip()]
    for i, text in enumerate(b.get("responses") or [], 1):
        text = str(text or "").strip().replace("\n", " ")
        if text:
            lines.append(f"c{i}: {text}")
    notes = "\n".join(x for x in lines if x)
    (GRADES / disk).mkdir(parents=True, exist_ok=True)
    f = GRADES / disk / f"{n}.txt"
    if not mine and not notes:
        f.unlink(missing_ok=True)
    else:
        f.write_text(f"overall: {mine}\nnotes:\n{notes}\n")
    # keep the reviewer's Q&A in learning/interactive-feedback/ in step with the saved feedback
    cfg, _ = check_repo(disk)
    r = subprocess.run([sys.executable, "-I", str(ROOT / "scripts" / "extract_feedback.py"), "--config", str(cfg),
                        "--repo", disk, check_run(b.get("run")), str(n)], capture_output=True, text=True, cwd=ROOT)
    if r.returncode:
        raise Err("feedback saved, but extracting it failed: " + r.stderr.strip()[-200:])
    return {"ok": True}


# ------------------------------------------------------------ proposals

PROPOSE_PROMPT = """You help refine a grader that rates GitHub pull requests. A human reviewed
one of its grades and left feedback. Propose edits to the grader's text files that
the feedback motivates.

Rules:
- Base every change on the human's feedback, not on your own opinion of the grader.
  If the feedback does not call for a change, return no proposals.
- Allowed files: `rubric.md` and `prompt.md` (generic grading rules), and the repo
  file `{repo_file}` (only for things specific to the target repo, such as ignored
  authors or titles). Nothing else.
- Generic wording only in rubric.md and prompt.md: no PR numbers, repo names or
  author names, nothing copied from the specific PR. Repo-specific rules go only
  in the repo file.
- Prefer a few sharp rules; check for conflicts with the existing text.
- Wrap markdown at 80 columns.
- `old` must be text copied exactly from the current file, and occur exactly once,
  or empty to append `new` at the end of the file.
- `why` is one sentence naming the feedback that motivated the change.

Return ONLY a JSON object, no prose, no code fences:
{{"proposals": [{{"file": "<file>", "old": "<exact text or empty>", "new": "<text>", "why": "<why>"}}]}}
"""


def allowed_files(rf):
    return {"rubric.md": ROOT / "rubric.md", "prompt.md": ROOT / "prompt.md",
            str(rf.relative_to(ROOT)): rf}


def validate(rf, proposals):
    """Return the proposals that are well formed and match the file text exactly once."""
    files, ok = allowed_files(rf), []
    for p in proposals if isinstance(proposals, list) else []:
        if not isinstance(p, dict) or p.get("file") not in files:
            continue
        old, new = p.get("old") or "", p.get("new") or ""
        if not isinstance(old, str) or not isinstance(new, str) or not (old or new):
            continue
        if old and files[p["file"]].read_text().count(old) != 1:
            continue
        ok.append({"file": p["file"], "old": old, "new": new, "why": str(p.get("why") or "")})
    return ok


def apply_proposals(rf, proposals):
    files = allowed_files(rf)
    good = validate(rf, proposals)
    if len(good) != len(proposals):
        raise Err("a proposal is stale or invalid (the file text changed); regenerate the proposals")
    for p in good:
        path = files[p["file"]]
        text = path.read_text()
        if p["old"]:
            if text.count(p["old"]) != 1:
                raise Err(f"stale proposal for {p['file']}: text not found exactly once")
            new = f"{AI_BEGIN}{p['new']}{AI_END}" if p["new"] else ""
            text = text.replace(p["old"], new)
        else:
            text = text.rstrip("\n") + f"\n\n{AI_BEGIN}\n{p['new'].strip()}\n{AI_END}\n"
        path.write_text(text)
    return current_run(rf)


def api_propose(b, role):
    disk, run, n = b["repo"], check_run(b["run"]), check_pr(b["pr"])
    cfg, rf = check_repo(disk)
    g = read_grade(disk, n)
    if not g["mine"] and not g["notes"]:
        raise Err("no feedback saved for this PR yet")
    res = (RESULTS / disk / run / f"{n}.json").read_text()

    def work(job):
        job.log.append("asking the model for proposals")
        prompt = (PROPOSE_PROMPT.format(repo_file=rf.relative_to(ROOT))
                  + f"\n# rubric.md\n{(ROOT / 'rubric.md').read_text()}\n"
                  f"# prompt.md\n{(ROOT / 'prompt.md').read_text()}\n"
                  f"# {rf.relative_to(ROOT)}\n{rf.read_text()}\n"
                  f"# PR meta\n{json.dumps(meta_of(disk, n), indent=1)}\n"
                  f"# The grader's result\n{res}\n"
                  f"# Human feedback (overall grade 1-5, then notes; `c<i>:` lines are about comment i)\n"
                  f"overall: {g['mine'] or '(none)'}\n{g['notes']}\n")
        job.result = {"proposals": validate(rf, ask_model(prompt, cfg).get("proposals"))}

    return {"job": start_job(work).id}


def api_apply(b, role):
    if role != "root":
        raise Err("only root can apply changes immediately; queue them instead", 403)
    _, rf = check_repo(b["repo"])
    return {"ok": True, "run": apply_proposals(rf, b.get("proposals") or [])}


# ---------------------------------------------------------------- queue
# One Markdown file per queued item, in webui-review-queue/<owner_name>/.

def fence(text):
    return "`" * (max([len(m) for m in re.findall(r"`+", text)] + [2]) + 1)


def block(text, lang="text"):
    f = fence(text)
    return f"{f}{lang}\n{text}\n{f}\n"


def render_item(item):
    one = lambda s: str(s).replace("\n", " ").strip()
    out = [f"<!-- AI generated by webui.py -->\n# Proposed changes for #{item['pr']}: {one(item['title'])}\n\n"]
    for k in ("repo", "run", "pr", "title", "role", "at", "status"):
        out.append(f"- {k}: {one(item[k])}\n")
    out.append("\nApply from the Queue tab of `scripts/webui.py` (root only); the Old and New blocks\n"
               "are what it applies, the Diff block is for reading.\n")
    for i, p in enumerate(item["proposals"], 1):
        diff = "\n".join(l for l in difflib.unified_diff(p["old"].splitlines(), p["new"].splitlines(),
                                                         lineterm="", n=0)
                         if not l.startswith(("---", "+++", "@@")))
        out.append(f"\n## {i}. {p['file']}\n\nWhy: {one(p['why'])}\n\nDiff:\n\n{block(diff, 'diff')}"
                   f"\nOld:\n\n{block(p['old'])}\nNew:\n\n{block(p['new'])}")
    return "".join(out)


def parse_item(text, qid, disk):
    head, *secs = re.split(r"^## \d+\. ", text, flags=re.M)
    meta = dict(re.findall(r"^- (\w+): (.*)$", head, flags=re.M))
    proposals = []
    for sec in secs:
        file, _, rest = sec.partition("\n")
        grab = lambda label: (re.search(rf"^{label}:\n\n(`{{3,}})\w*\n(.*?)\n\1$", rest, re.S | re.M) or [0, 0, ""])[2]
        why = re.search(r"^Why: (.*)$", rest, re.M)
        proposals.append({"file": file.strip(), "old": grab("Old"), "new": grab("New"),
                          "why": why[1] if why else ""})
    return {"id": qid, "repo": disk, "run": meta.get("run", ""), "pr": int(meta.get("pr", 0)),
            "title": meta.get("title", ""), "role": meta.get("role", ""), "at": meta.get("at", ""),
            "status": meta.get("status", "pending"), "proposals": proposals}


def queue_items():
    items = []
    for f in QUEUE.glob("*/*.md"):
        try:
            items.append(parse_item(f.read_text(), f.stem, f.parent.name))
        except (ValueError, TypeError):
            pass
    return sorted(items, key=lambda i: i["id"], reverse=True)


def queue_file(disk, qid):
    check_repo(disk)
    if not re.match(r"^[\w.-]+$", str(qid)):
        raise Err("bad id")
    f = QUEUE / disk / f"{qid}.md"
    if not f.exists():
        raise Err("no such queue item")
    return f


def set_status(f, status):
    f.write_text(re.sub(r"^- status: .*$", f"- status: {status}", f.read_text(), count=1, flags=re.M))


def api_enqueue(b, role):
    disk, n = b["repo"], check_pr(b["pr"])
    _, rf = check_repo(disk)
    proposals = validate(rf, b.get("proposals") or [])
    if not proposals:
        raise Err("nothing to queue")
    qid = f"{time.strftime('%Y%m%d-%H%M%S')}-{n}"
    (QUEUE / disk).mkdir(parents=True, exist_ok=True)
    item = {"id": qid, "repo": disk, "run": check_run(b.get("run")), "pr": n,
            "title": meta_of(disk, n).get("title", ""), "role": role,
            "at": time.strftime("%Y-%m-%d %H:%M:%S"), "proposals": proposals, "status": "pending"}
    (QUEUE / disk / f"{qid}.md").write_text(render_item(item))
    return {"ok": True, "id": qid}


def api_queue_apply(b, role):
    if role != "root":
        raise Err("only root can apply queued changes", 403)
    f = queue_file(b["repo"], b.get("id"))
    item = parse_item(f.read_text(), f.stem, b["repo"])
    if item["status"] != "pending":
        raise Err(f"already {item['status']}")
    _, rf = check_repo(b["repo"])
    run = apply_proposals(rf, item["proposals"])
    set_status(f, "applied")
    return {"ok": True, "run": run}


def api_queue_dismiss(b, role):
    if role != "root":
        raise Err("only root can dismiss queued changes", 403)
    f = queue_file(b["repo"], b.get("id"))
    if parse_item(f.read_text(), f.stem, b["repo"])["status"] == "pending":
        set_status(f, "dismissed")
    return {"ok": True}


def api_repos():
    out = []
    for cfg in sorted(ROOT.glob("*.cfg")):
        if cfg.is_symlink():
            continue
        rel = parse_cfg(cfg).get("repo")
        rf = ROOT / rel if rel else None
        name = canonical(rf) if rf and rf.is_file() else None
        if name:
            out.append({"repo": name, "cfg": cfg.name})
    return out


def api_example(b, role):
    """Save a selection of the PR's diff plus a comment as a Q&A file for the grader."""
    disk, n = b["repo"], check_pr(b["pr"])
    check_repo(disk)
    comment = str(b.get("comment") or "").strip()
    if not comment:
        raise Err("write a comment first")
    d = DATA / disk / "prs" / str(n) / "diff.patch"
    if not d.exists():
        raise Err("no diff for this PR")
    section, inside, found = [], False, False
    for line in d.read_text().splitlines():
        if line.startswith("diff --git"):
            inside = line.split(" b/", 1)[-1] == b.get("file")
            found = found or inside
        elif inside:
            section.append(line)
    try:
        a, z = int(b["from"]), int(b["to"])
    except (KeyError, TypeError, ValueError):
        raise Err("bad selection")
    if not found or not section or not 0 <= a <= z < len(section):
        raise Err("the selection is not in the diff")
    z = min(z, a + 199)
    nums, nl = [], 0  # new-file line number of each selected row, where it has one
    for i, line in enumerate(section[:z + 1]):
        m = re.match(r"^@@ -\d+(?:,\d+)? \+(\d+)", line)
        if m:
            nl = int(m[1])
        elif nl and line[:1] in ("+", " "):
            if i >= a:
                nums.append(nl)
            nl += 1
    snippet = "\n".join(section[a:z + 1])
    f = fence(snippet)
    lines = [f"<!-- AI generated by webui.py from the diff of PR {n} -->",
             f"# Example from PR {n}: {meta_of(disk, n).get('title', '').strip()}", "",
             f"- repo: {disk.replace('_', '/', 1)}", f"- saved: {time.strftime('%Y-%m-%d %H:%M:%S')}",
             f"- file: {b['file']}"]
    if nums:
        lines.append(f"- new-file lines: {nums[0]}-{nums[-1]}")
    lines += ["", f"## Q: Code from the diff of {b['file']}", f"{f}diff", snippet, f, "", f"A: {comment}"]
    out = LEARN / disk
    out.mkdir(parents=True, exist_ok=True)
    t = time.time()
    while (out / f"{n}-example-{time.strftime('%Y%m%d-%H%M%S', time.localtime(t))}.md").exists():
        t += 1
    name = f"{n}-example-{time.strftime('%Y%m%d-%H%M%S', time.localtime(t))}.md"
    (out / name).write_text("\n".join(lines) + "\n")
    return {"ok": True, "file": name}


def api_explain(b, role):
    disk, run, n = b["repo"], check_run(b["run"]), check_pr(b["pr"])
    cfg, _ = check_repo(disk)
    q = (b.get("question") or "").strip()

    def work(job):
        code, text = run_script(job, cfg, "explain", "--repo", disk, run, str(n), *([q] if q else []))
        if code:
            raise Err("explain failed")
        job.result = {"text": text}

    return {"job": start_job(work).id}


